    <div className="relative border-b border-white/10 px-2 pb-5 pt-2"><span className="text-[10px] font-extrabold tracking-[.2em] text-[#f16133]">DCAMPAIGN</span><strong className="mt-1 block font-display text-xl">Sales CRM</strong><button aria-label="Close menu" onClick={()=>setMobile(false)} className="absolute right-1 top-2 lg:hidden"><X/></button></div>
